<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_login();$session=current_user();$stmt=$pdo->prepare('SELECT * FROM users WHERE id=?');$stmt->execute([$session['id']]);$user=$stmt->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='profile'){$name=trim((string)($_POST['name']??''));$username=strtolower(trim((string)($_POST['username']??'')));$email=strtolower(trim((string)($_POST['email']??'')));$bio=trim((string)($_POST['bio']??''));$website=trim((string)($_POST['website']??''));if(mb_strlen($name)<2)throw new RuntimeException('Nama terlalu pendek.');if(!preg_match('/^[a-z0-9-]{3,60}$/',$username))throw new RuntimeException('Username hanya boleh huruf kecil, angka, dan tanda hubung.');if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Email tidak valid.');$stmt=$pdo->prepare('SELECT COUNT(*) FROM users WHERE (email=? OR username=?) AND id<>?');$stmt->execute([$email,$username,$user['id']]);if($stmt->fetchColumn())throw new RuntimeException('Email atau username sudah digunakan.');$pdo->prepare('UPDATE users SET name=?,username=?,email=?,bio=?,website=? WHERE id=?')->execute([$name,$username,$email,$bio,$website,$user['id']]);$_SESSION['user']['name']=$name;$_SESSION['user']['email']=$email;flash('success','Profil kreator berhasil diperbarui.');}elseif($action==='password'){$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');if(!password_verify($current,$user['password']))throw new RuntimeException('Password saat ini tidak sesuai.');if(strlen($new)<8)throw new RuntimeException('Password baru minimal 8 karakter.');if($new!==($_POST['password_confirmation']??''))throw new RuntimeException('Konfirmasi password tidak sama.');$pdo->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$user['id']]);flash('success','Password berhasil diperbarui.');}}catch(Throwable $e){flash('error',$e->getMessage());}header('Location: profile');exit;}$flash=pull_flash();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profil Kreator — Semarakin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container profile-page"><div class="page-head"><span class="eyebrow">Identitas kreator</span><h1 class="page-title" style="margin-top:12px">Profil saya</h1><p class="subtitle">Bangun identitas yang mudah dikenal audiens.</p></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><div class="profile-grid"><aside class="profile-summary"><div class="avatar"><?=e(strtoupper(mb_substr($user['name'],0,1)))?></div><h2><?=e($user['name'])?><?=$user['is_verified']?' ✓':''?></h2><p>@<?=e($user['username'])?></p><span class="visibility visibility-public"><?=e(ucfirst($user['role']))?></span><a class="btn btn-secondary btn-sm" style="margin-top:18px" href="creator/<?=e($user['username'])?>">Lihat profil publik</a></aside><div class="profile-forms"><section class="panel"><div class="form-heading"><span class="form-icon">✦</span><div><h2>Profil publik</h2><p>Ditampilkan pada setiap karya Anda.</p></div></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="profile"><div class="field"><label>Nama</label><input name="name" value="<?=e($user['name'])?>" required></div><div class="field"><label>Username</label><input name="username" value="<?=e($user['username'])?>" pattern="[a-z0-9-]{3,60}" required></div><div class="field"><label>Email</label><input name="email" type="email" value="<?=e($user['email'])?>" required></div><div class="field"><label>Bio</label><textarea name="bio" rows="3" maxlength="300"><?=e($user['bio'])?></textarea></div><div class="field"><label>Website</label><input name="website" type="url" value="<?=e($user['website'])?>" placeholder="https://"></div><button class="btn btn-primary">Simpan profil</button></form></section><section class="panel"><div class="form-heading"><span class="form-icon">●</span><div><h2>Keamanan akun</h2><p>Perbarui password secara berkala.</p></div></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="password"><div class="field"><label>Password saat ini</label><input name="current_password" type="password" required></div><div class="field"><label>Password baru</label><input name="new_password" type="password" minlength="8" required></div><div class="field"><label>Konfirmasi password</label><input name="password_confirmation" type="password" minlength="8" required></div><button class="btn btn-primary">Ubah password</button></form></section></div></div></main><footer class="footer">Semarakin · Produk digital dari Apins Digital</footer></body></html>
